
<template>
  <div>
    <div style="margin-bottom: 5px;">端口: <el-input size="mini" v-model="utisLDeviceServer.port" style="width: 140px;"/></div>
    <el-tabs type="border-card" v-model="utisLDeviceServerValue">
      <el-tab-pane v-for="(v,i) in utisLDeviceServer.devices" :key="i" :label="v['名称']" :name="v.id" style="padding-bottom: 20px;">
        <div style="display: flex;margin-top: 20px;">
          <el-descriptions class="margin-top" :column="1" border style="width: 400px;">
            <template v-for="(item, key) in v">
              <el-descriptions-item v-if="key != '名称' && key != 'id' && key != 'deviceCode' && key != 'children'" :key="key">
                <template slot="label">{{ key }}</template>
                <el-input size="small" v-model="formData[v.id][key]"></el-input>
              </el-descriptions-item>
            </template>
          </el-descriptions>
          <el-tabs v-model="editableTabsValue" tab-position="left" v-if="v.children && v.children.length > 0" :closable="v.children.length > 1" @tab-remove="removeTab">
            <el-tab-pane v-for="(item, index) in v.children" :key="index" :label="item['名称']" :name="item.id">
              <el-descriptions class="margin-top" :column="1" border style="width: 400px;">
                <template v-for="(citme, ckey, cindex) in item">
                  <el-descriptions-item v-if="ckey != '名称' && ckey != 'id'" :key="cindex">
                    <template slot="label">{{ ckey }}</template>
                    <el-input size="small" v-model="formData[item.id][ckey]"></el-input>
                  </el-descriptions-item>
                </template>
              </el-descriptions>
            </el-tab-pane>
          </el-tabs>
        </div>
        <el-button v-if="v.children && v.children.length > 0" class="buttonCss" size="mini" @click="addTab(0)" icon="el-icon-plus"></el-button>
      </el-tab-pane>
    </el-tabs>
    <el-button style="margin: 10px 0 0 380px;" type="primary" size="mini" @click="submit">更新</el-button>
  </div>
</template>
<script>
import { getCfg, setCfg } from '@/api/webCfg'
export default {
  name: 'jingShiDeng',
  props: ['filepath'],
  data() {
    return{
      utisLDeviceServerPort: '2333',
      utisLDeviceServer:[],
      utisLDeviceServerValue: '0',
      editableTabsValue: '0',
      formData: {}
    }
  },
  methods: {
    getCfgFun() {
      getCfg({ filepath: this.filepath }).then((res) => {
        res.devices.forEach((item,index) => {
          item.id = '' + index + item.deviceCode
          this.formData[item.id] = {}
          for( let cv in item ) {
            this.formData[item.id][cv] = item[cv]
          }
          if (item.children && item.children.length > 0) {
            item.children.forEach((v, index) => {
              v.id = index + v['ip端口']
              this.formData[v.id] = {}
              for( let cv in v ) {
                this.formData[v.id][cv] = v[cv]
              }
            })
          }
        })
        this.utisLDeviceServer = res
        this.utisLDeviceServerValue = res.devices[0].id
        this.editableTabsValue = res.devices[0].children && res.devices[0].children[0].id
        this.formData = JSON.parse(JSON.stringify(this.formData))
      })
    },
    addTab() {
      let data = this.utisLDeviceServer.devices.filter((filt) => { return filt.deviceCode == this. utisLDeviceServerValue})[0]
      let obj = {
        'id': +new Date() + '',
        'ip端口':"192.168.1.101:8889",
        '全息编号': "QuanXiId1,QuanXiId2,QuanXiId3,QuanXiId4",
        '名称': "警示灯网络控制器",
        '灯编号': "1-2;3-4",
        '连接方式': "tcp"
      }
      data.children.push(obj);
      this.formData[obj.id] = obj
      this.editableTabsValue = obj.id;
    },
    removeTab(targetName) {
      let data = this.utisLDeviceServer.devices.filter((filt) => { return filt.deviceCode == this. utisLDeviceServerValue})[0]
      if (data.children.length > 1) {
        data.children = data.children.filter(tab => tab.id !== targetName);
        if (data.children[data.children.length - 1]) {
          this.editableTabsValue = data.children[data.children.length - 1].id
        }
      }
    },
    submit() {
      this.utisLDeviceServer.devices.forEach((item) => {
        for( let cv in item ) {
          if (cv != 'children') {
            item[cv] = this.formData[item.id][cv]
          }
        }
        if (item.children && item.children.length > 0) {
          item.children.forEach((v) => {
            for( let cv in v ) {
              v[cv] = this.formData[v.id][cv]
            }
          })
        }
      })
      let params = {
        filepath: this.filepath,
        fielData: this.utisLDeviceServer
      }
      setCfg(params).then(res => {
        if (res.code == 200) {
          this.$message({
            message: res.msg,
            type: 'success'
          });
        }
      })
    }
  },
  mounted(){
    this.getCfgFun()
  }
}
</script>
