import router from '@/router'


const whiteList = ['/login']

router.beforeEach(((to, from, next) => {
  let token = sessionStorage.getItem('token')
  if(token){
    if (to.path === '/login'){
      next({path:'/'})
    }else if (whiteList.indexOf(to.path) !== -1) {
      next()
    }else{
      next()
    }
  }else{
    if (whiteList.indexOf(to.path) !== -1){
      next()
    }else{
      next(`/login`)
    }
  }
}))
